mixed-port: 7890
allow-lan: false
mode: rule
proxies:
  - {name: "剩余流量：3.81 TB", type: ss, server: 127.0.0.1, port: 1, cipher: aes-128-gcm, password: info-only, udp: true}
  - {name: "套餐到期：长期有效", type: ss, server: 127.0.0.1, port: 2, cipher: aes-128-gcm, password: info-only, udp: true}
  - {name: "🇯🇵 日本 AWS01", type: vless, server: jp1.airport.example, port: 443, uuid: 11111111-1111-4111-8111-111111111101, network: tcp, tls: true, udp: true, flow: xtls-rprx-vision, servername: www.example.com, client-fingerprint: chrome, reality-opts: {public-key: fake-public-key-jp1, short-id: 0a1b2c3d}}
  - {name: "🇯🇵 日本 AWS08", type: vless, server: jp8.airport.example, port: 443, uuid: 11111111-1111-4111-8111-111111111108, network: tcp, tls: true, udp: true, flow: xtls-rprx-vision, servername: www.example.com, client-fingerprint: chrome, reality-opts: {public-key: fake-public-key-jp8, short-id: 0a1b2c3d}}
  - {name: "🇺🇸 美国 01", type: vless, server: us1.airport.example, port: 443, uuid: 11111111-1111-4111-8111-111111111201, network: ws, tls: true, udp: true, servername: us1.airport.example, ws-opts: {path: /fake-path, headers: {Host: us1.airport.example}}}
  - {name: "🇺🇸 美国 Hy2 01", type: hysteria2, server: us2.airport.example, port: 8443, password: fake-hy2-password, sni: us2.airport.example, skip-cert-verify: false, udp: true}
  - {name: "🇸🇬 新加坡 01", type: hysteria2, server: sg1.airport.example, port: 8443, password: fake-hy2-password, sni: sg1.airport.example, skip-cert-verify: false, udp: true}
  - {name: "🇭🇰 香港 01", type: vless, server: hk1.airport.example, port: 443, uuid: 11111111-1111-4111-8111-111111111301, network: tcp, tls: true, udp: true, flow: xtls-rprx-vision, servername: www.example.com, client-fingerprint: chrome, reality-opts: {public-key: fake-public-key-hk1, short-id: 0a1b2c3d}}
  - {name: "🇹🇼 台湾 01", type: vless, server: tw1.airport.example, port: 443, uuid: 11111111-1111-4111-8111-111111111401, network: tcp, tls: true, udp: true, flow: xtls-rprx-vision, servername: www.example.com, client-fingerprint: chrome, reality-opts: {public-key: fake-public-key-tw1, short-id: 0a1b2c3d}}
proxy-groups:
  - {name: 节点选择, type: select, proxies: ["🇯🇵 日本 AWS01", "🇯🇵 日本 AWS08", "🇺🇸 美国 01", "🇺🇸 美国 Hy2 01", "🇸🇬 新加坡 01", "🇭🇰 香港 01", "🇹🇼 台湾 01"]}
rules:
  - MATCH,节点选择
